// Python-compatible Unicode primitives, built on Node's native Unicode
// property escapes.  Python strings are sequences of code points, so every
// helper here works on code points rather than UTF-16 units.

// str.isprintable(): non printable == general category "Other" or
// "Separator", except for the ASCII space.
const RE_OTHER_OR_SEPARATOR = /^[\p{C}\p{Z}]$/u;
const RE_DECIMAL_DIGIT = /^\p{Nd}$/u;

// Characters str.splitlines() treats as line boundaries.
const LINE_BOUNDARIES = new Set([
  '\n', '\r', '\v', '\f', '\x1c', '\x1d', '\x1e', '', ' ', ' ',
]);

// str.isspace(): ASCII whitespace, the file/group/record separators, NEL,
// the line/paragraph separators and everything in category Zs.
const ASCII_SPACES = new Set([
  '\t', '\n', '\v', '\f', '\r', ' ', '\x1c', '\x1d', '\x1e', '\x1f',
  '', ' ', ' ',
]);
const RE_ZS = /^\p{Zs}$/u;

export function codePoints(s) {
  return Array.from(s);
}

export function cpLength(s) {
  let n = 0;
  for (const _ of s) n += 1;
  return n;
}

export function cpSlice(s, end) {
  return codePoints(s).slice(0, end).join('');
}

export function isPrintable(ch) {
  if (ch === ' ') return true;
  return !RE_OTHER_OR_SEPARATOR.test(ch);
}

export function isSpace(ch) {
  return ASCII_SPACES.has(ch) || RE_ZS.test(ch);
}

// unicodedata.decimal(ch) for category Nd characters, -1 otherwise.
// Every Nd block is a contiguous run of exactly ten code points, so the
// zero digit is found by walking backwards at most nine positions.
export function decimalValue(ch) {
  if (!RE_DECIMAL_DIGIT.test(ch)) return -1;
  const cp = ch.codePointAt(0);
  let zero = cp;
  while (zero > 0 && cp - zero < 9 &&
         RE_DECIMAL_DIGIT.test(String.fromCodePoint(zero - 1))) {
    zero -= 1;
  }
  return cp - zero;
}

export function splitLines(s) {
  const chars = codePoints(s);
  const lines = [];
  let current = '';
  for (let i = 0; i < chars.length; i += 1) {
    const ch = chars[i];
    if (!LINE_BOUNDARIES.has(ch)) {
      current += ch;
      continue;
    }
    if (ch === '\r' && chars[i + 1] === '\n') i += 1;
    lines.push(current);
    current = '';
  }
  if (current !== '') lines.push(current);
  return lines;
}

