// Python's repr()/str() for the value shapes this program prints.
//
// Value mapping used across the port:
//   Python str   -> JS string
//   Python int   -> JS BigInt (Python ints are unbounded)
//   Python dict  -> JS Map    (insertion ordered, like dict)
//   Python list  -> JS Array

import { codePoints, isPrintable } from './pyunicode.mjs';

function hex(cp, width) {
  return cp.toString(16).padStart(width, '0');
}

// CPython's unicode_repr(): prefer single quotes, switch to double quotes
// only when the string contains ' but no ".
export function reprStr(s) {
  const chars = codePoints(s);
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of chars) {
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (isPrintable(ch)) {
      out += ch;
    } else {
      const cp = ch.codePointAt(0);
      if (cp < 0x100) out += '\\x' + hex(cp, 2);
      else if (cp < 0x10000) out += '\\u' + hex(cp, 4);
      else out += '\\U' + hex(cp, 8);
    }
  }
  return out + quote;
}

export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'bigint') return value.toString();
  if (value instanceof Map) {
    const items = [];
    for (const [key, item] of value) {
      items.push(`${pyRepr(key)}: ${pyRepr(item)}`);
    }
    return `{${items.join(', ')}}`;
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(', ')}]`;
  }
  throw new TypeError(`cannot repr ${typeof value}`);
}

// print(value): str() of containers is their repr, bare strings print raw.
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

