// json.dumps() with the CPython defaults: ensure_ascii=True and the
// ", " / ": " separators.

// Marker for text that must be spliced into the output verbatim (used for
// numbers that were shortened to a bare digit run).
export class RawJson {
  constructor(text) {
    this.text = text;
  }
}

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['"', '\\"'],
  ['\b', '\\b'],
  ['\f', '\\f'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

// py_encode_basestring_ascii(): everything outside 0x20..0x7e is escaped,
// astral code points as a surrogate pair.  Iterating UTF-16 units gives
// exactly that pairing for free.
export function encodeString(s) {
  let out = '"';
  for (let i = 0; i < s.length; i += 1) {
    const ch = s[i];
    const escape = SHORT_ESCAPES.get(ch);
    if (escape !== undefined) {
      out += escape;
      continue;
    }
    const code = s.charCodeAt(i);
    if (code < 0x20 || code > 0x7e) {
      out += '\\u' + code.toString(16).padStart(4, '0');
    } else {
      out += ch;
    }
  }
  return out + '"';
}

export function jsonDumps(value) {
  if (value instanceof RawJson) return value.text;
  if (typeof value === 'string') return encodeString(value);
  if (typeof value === 'bigint') return value.toString();
  if (value instanceof Map) {
    const items = [];
    for (const [key, item] of value) {
      items.push(`${encodeString(key)}: ${jsonDumps(item)}`);
    }
    return `{${items.join(', ')}}`;
  }
  if (Array.isArray(value)) {
    return `[${value.map(jsonDumps).join(', ')}]`;
  }
  throw new TypeError(`cannot serialize ${typeof value}`);
}

