// int(str) as CPython implements it: surrounding whitespace is stripped, an
// optional ASCII sign is allowed, digits may be any Unicode decimal digit and
// single underscores may separate digits.  Returns a BigInt, or null when the
// text is not a valid integer literal.

import { codePoints, decimalValue, isSpace } from './pyunicode.mjs';

export function pyInt(text) {
  const chars = codePoints(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isSpace(chars[start])) start += 1;
  while (end > start && isSpace(chars[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (chars[start] === '+' || chars[start] === '-')) {
    negative = chars[start] === '-';
    start += 1;
  }

  let digits = '';
  let afterDigit = false;
  for (let i = start; i < end; i += 1) {
    const ch = chars[i];
    if (ch === '_') {
      // Underscores are only allowed between digits.
      if (!afterDigit) return null;
      afterDigit = false;
      continue;
    }
    const value = decimalValue(ch);
    if (value < 0) return null;
    digits += String(value);
    afterDigit = true;
  }
  if (!afterDigit) return null;

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

