// CPython decodes sys.argv with the surrogateescape error handler, so bytes
// that are not valid UTF-8 survive as lone surrogates (U+DC80..U+DCFF) and are
// visible in repr() output.  Node decodes process.argv with U+FFFD
// replacement, so the raw bytes are recovered from /proc/self/cmdline when it
// is available and process.argv is used as the fallback.

import { readFileSync } from 'node:fs';

export function decodeSurrogateEscape(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const lead = bytes[i];
    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }
    let extra = 0;
    let value = 0;
    let lowest = 0;
    if (lead >= 0xc2 && lead <= 0xdf) {
      extra = 1;
      value = lead & 0x1f;
      lowest = 0x80;
    } else if (lead >= 0xe0 && lead <= 0xef) {
      extra = 2;
      value = lead & 0x0f;
      lowest = 0x800;
    } else if (lead >= 0xf0 && lead <= 0xf4) {
      extra = 3;
      value = lead & 0x07;
      lowest = 0x10000;
    }
    let decoded = null;
    if (extra > 0 && i + extra < bytes.length) {
      let candidate = value;
      let valid = true;
      for (let k = 1; k <= extra; k += 1) {
        if ((bytes[i + k] & 0xc0) !== 0x80) {
          valid = false;
          break;
        }
        candidate = (candidate << 6) | (bytes[i + k] & 0x3f);
      }
      if (valid && candidate >= lowest && candidate <= 0x10ffff &&
          !(candidate >= 0xd800 && candidate <= 0xdfff)) {
        decoded = candidate;
      }
    }
    if (decoded === null) {
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
    } else {
      out += String.fromCodePoint(decoded);
      i += extra + 1;
    }
  }
  return out;
}

function splitNulTerminated(buffer) {
  const parts = [];
  let start = 0;
  for (let i = 0; i < buffer.length; i += 1) {
    if (buffer[i] === 0) {
      parts.push(buffer.subarray(start, i));
      start = i + 1;
    }
  }
  if (start < buffer.length) parts.push(buffer.subarray(start));
  return parts;
}

// The script arguments are the trailing entries of the command line, so they
// can be lined up with process.argv.slice(2) by counting from the end.
export function scriptArgs() {
  const wanted = process.argv.length - 2;
  if (wanted <= 0) return [];
  try {
    const parts = splitNulTerminated(readFileSync('/proc/self/cmdline'));
    if (parts.length >= wanted) {
      return parts.slice(parts.length - wanted).map(decodeSurrogateEscape);
    }
  } catch {
    // /proc is unavailable; fall back to Node's decoded argv.
  }
  return process.argv.slice(2);
}

