// Synchronous stdout/stderr writes.  Node's process.stdout is asynchronous
// when it points at a pipe, so process.exit() can drop buffered output;
// fs.writeSync avoids that and keeps stdout/stderr ordering intact.

import { writeSync } from 'node:fs';

function writeAll(fd, text) {
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue;
      if (error.code === 'EPIPE') return;
      throw error;
    }
  }
}

export function print(text) {
  writeAll(1, `${text}\n`);
}

export function writeOut(text) {
  writeAll(1, text);
}

export function writeErr(text) {
  writeAll(2, text);
}

