// A faithful subset of argparse.ArgumentParser covering optional-only parsers:
// "--opt value" and "--opt=value" forms, unambiguous long-option
// abbreviations, the -h/--help action, "--" switching to positionals, and the
// usage/error/help text argparse emits (Python 3.10+ wording).

import { pyInt } from './pyint.mjs';
import { reprStr } from './pyrepr.mjs';
import { writeErr, writeOut } from './pyio.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor(optionStrings, { dest, type, required, help, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type ?? 'str';
    this.required = required ?? false;
    this.help = help ?? null;
    this.isHelp = isHelp ?? false;
  }

  // "--a A" / "-h, --help"
  formatInvocation() {
    if (this.isHelp) return this.optionStrings.join(', ');
    const metavar = this.dest.toUpperCase();
    return this.optionStrings.map((opt) => `${opt} ${metavar}`).join(', ');
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.addArgument(['-h', '--help'], {
      dest: 'help',
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const dest = options.dest ?? strings[strings.length - 1].replace(/^-+/, '');
    const action = new Action(strings, { ...options, dest });
    this.actions.push(action);
    return action;
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const invocation = action.isHelp
        ? action.optionStrings[0]
        : `${action.optionStrings[0]} ${action.dest.toUpperCase()}`;
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => action.formatInvocation());
    // argparse aligns help text in a column computed from the longest
    // invocation, capped so that it never exceeds the action max length.
    const width = Math.max(...invocations.map((text) => text.length));
    const lines = [];
    for (let i = 0; i < this.actions.length; i += 1) {
      const action = this.actions[i];
      if (action.help) {
        lines.push(`  ${invocations[i].padEnd(width)}  ${action.help}`);
      } else {
        lines.push(`  ${invocations[i]}`);
      }
    }
    return `${this.formatUsage()}\noptions:\n${lines.join('\n')}\n`;
  }

  exitWithHelp() {
    writeOut(this.formatHelp());
    process.exit(0);
  }

  error(message) {
    writeErr(this.formatUsage());
    writeErr(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  // argparse._parse_optional(): decide whether a token is an option.
  matchOption(token) {
    if (token === '' || token[0] !== '-') return null;
    for (const action of this.actions) {
      if (action.optionStrings.includes(token)) {
        return { action, explicitValue: null, token };
      }
    }
    if (token.length === 1) return null;
    const eq = token.indexOf('=');
    if (eq > 0) {
      const name = token.slice(0, eq);
      for (const action of this.actions) {
        if (action.optionStrings.includes(name)) {
          return { action, explicitValue: token.slice(eq + 1), token: name };
        }
      }
    }
    const abbreviated = this.matchAbbreviation(token);
    if (abbreviated) return abbreviated;
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;
    return { action: null, explicitValue: null, token };
  }

  matchAbbreviation(token) {
    const eq = token.indexOf('=');
    const prefix = eq > 0 ? token.slice(0, eq) : token;
    const explicitValue = eq > 0 ? token.slice(eq + 1) : null;
    if (!prefix.startsWith('--')) return null;
    const matches = [];
    for (const action of this.actions) {
      for (const option of action.optionStrings) {
        if (option.startsWith(prefix)) matches.push({ action, option });
      }
    }
    if (matches.length === 0) return null;
    if (matches.length > 1) {
      const options = matches.map((m) => m.option).join(', ');
      this.error(`ambiguous option: ${prefix} could match ${options}`);
    }
    return { action: matches[0].action, explicitValue, token: prefix };
  }

  convert(action, raw) {
    if (action.type !== 'int') return raw;
    const value = pyInt(raw);
    if (value === null) {
      this.error(
        `argument ${action.optionStrings.join('/')}: invalid int value: ${reprStr(raw)}`,
      );
    }
    return value;
  }

  parseArgs(argv) {
    const namespace = new Map();
    for (const action of this.actions) {
      if (!action.isHelp) namespace.set(action.dest, null);
    }
    const extras = [];
    let onlyPositionals = false;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];
      if (onlyPositionals) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        // argparse only drops the first "--" while consuming a positional;
        // with no positionals defined it stays behind as an extra.
        onlyPositionals = true;
        extras.push(token);
        continue;
      }
      const match = this.matchOption(token);
      if (match === null) {
        extras.push(token);
        continue;
      }
      if (match.action === null) {
        extras.push(token);
        continue;
      }
      if (match.action.isHelp) {
        this.exitWithHelp();
      }
      let raw = match.explicitValue;
      if (raw === null) {
        if (i + 1 >= argv.length || this.looksLikeOption(argv[i + 1])) {
          this.error(
            `argument ${match.action.optionStrings.join('/')}: expected one argument`,
          );
        }
        i += 1;
        raw = argv[i];
      }
      namespace.set(match.action.dest, this.convert(match.action, raw));
    }

    const missing = this.actions
      .filter((action) => action.required && namespace.get(action.dest) === null)
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  looksLikeOption(token) {
    if (token === '' || token[0] !== '-') return false;
    if (token === '--') return true;
    if (token.length === 1) return false;
    if (this.matchOption(token) !== null) return true;
    return false;
  }
}

// argparse reports the offending text with Python's repr().
function quote(text) {
  return text.includes("'") && !text.includes('"') ? `"${text}"` : `'${text}'`;
}

