// Port of the parts of Python's difflib that DeepDiff uses when it reports a
// change between two multiline strings: SequenceMatcher (including the
// autojunk heuristic) and unified_diff.

export class SequenceMatcher {
  constructor(isjunk, a, b, autojunk = true) {
    this.isjunk = isjunk;
    this.a = a;
    this.b = b;
    this.autojunk = autojunk;
    this.matchingBlocks = null;
    this.chainB();
  }

  chainB() {
    const b = this.b;
    const b2j = new Map();
    for (let i = 0; i < b.length; i += 1) {
      const indices = b2j.get(b[i]);
      if (indices === undefined) b2j.set(b[i], [i]);
      else indices.push(i);
    }

    this.bjunk = new Set();
    if (this.isjunk) {
      for (const element of [...b2j.keys()]) {
        if (this.isjunk(element)) {
          this.bjunk.add(element);
          b2j.delete(element);
        }
      }
    }

    // Elements appearing in more than 1% of a long b are treated as junk.
    this.bpopular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [element, indices] of [...b2j]) {
        if (indices.length > ntest) {
          this.bpopular.add(element);
          b2j.delete(element);
        }
      }
    }
    this.b2j = b2j;
  }

  findLongestMatch(alo, ahi, blo, bhi) {
    const { a, b, b2j } = this;
    const isbjunk = (element) => this.bjunk.has(element);
    let besti = alo;
    let bestj = blo;
    let bestsize = 0;

    let j2len = new Map();
    for (let i = alo; i < ahi; i += 1) {
      const newj2len = new Map();
      const indices = b2j.get(a[i]) ?? [];
      for (const j of indices) {
        if (j < blo) continue;
        if (j >= bhi) break;
        const k = (j2len.get(j - 1) ?? 0) + 1;
        newj2len.set(j, k);
        if (k > bestsize) {
          besti = i - k + 1;
          bestj = j - k + 1;
          bestsize = k;
        }
      }
      j2len = newj2len;
    }

    while (besti > alo && bestj > blo && !isbjunk(b[bestj - 1]) &&
           a[besti - 1] === b[bestj - 1]) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (besti + bestsize < ahi && bestj + bestsize < bhi &&
           !isbjunk(b[bestj + bestsize]) &&
           a[besti + bestsize] === b[bestj + bestsize]) {
      bestsize += 1;
    }

    while (besti > alo && bestj > blo && isbjunk(b[bestj - 1]) &&
           a[besti - 1] === b[bestj - 1]) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (besti + bestsize < ahi && bestj + bestsize < bhi &&
           isbjunk(b[bestj + bestsize]) &&
           a[besti + bestsize] === b[bestj + bestsize]) {
      bestsize += 1;
    }

    return [besti, bestj, bestsize];
  }

  getMatchingBlocks() {
    if (this.matchingBlocks !== null) return this.matchingBlocks;
    const la = this.a.length;
    const lb = this.b.length;
    const queue = [[0, la, 0, lb]];
    const blocks = [];
    while (queue.length > 0) {
      const [alo, ahi, blo, bhi] = queue.pop();
      const [i, j, k] = this.findLongestMatch(alo, ahi, blo, bhi);
      if (k > 0) {
        blocks.push([i, j, k]);
        if (alo < i && blo < j) queue.push([alo, i, blo, j]);
        if (i + k < ahi && j + k < bhi) queue.push([i + k, ahi, j + k, bhi]);
      }
    }
    blocks.sort((x, y) => (x[0] - y[0]) || (x[1] - y[1]) || (x[2] - y[2]));

    // Collapse adjacent equal blocks.
    let i1 = 0;
    let j1 = 0;
    let k1 = 0;
    const nonAdjacent = [];
    for (const [i2, j2, k2] of blocks) {
      if (i1 + k1 === i2 && j1 + k1 === j2) {
        k1 += k2;
      } else {
        if (k1 > 0) nonAdjacent.push([i1, j1, k1]);
        i1 = i2;
        j1 = j2;
        k1 = k2;
      }
