// Delta objects, and the shortened representation they print.
//
// print(Delta(diff)) emits "<Delta: {json}>" where the JSON is the delta
// mapping: values_changed keeps only the new value, dictionary_item_added maps
// each path to the added value.
//
// Long values are shortened first.  The thresholds below were calibrated
// against the reference implementation: a leaf is left alone while its length
// in code points plus the combined length of the keys leading to it stays
// within LENGTH_ALLOWANCE, and is otherwise cut down to a budget that shrinks
// with both the key lengths and the nesting depth.

import { cpLength, cpSlice } from './pyunicode.mjs';
import { jsonDumps, RawJson } from './pyjson.mjs';

const LENGTH_ALLOWANCE = 100;
const BUDGET_BASE = 66;
const BUDGET_PER_LEVEL = 11;

const JSON_INTEGER = /^-?\d+$/;

function leafText(value) {
  return typeof value === 'string' ? value : value.toString();
}

function shortenLeaf(value, keys) {
  const text = leafText(value);
  const keyLength = keys.reduce((total, key) => total + cpLength(key), 0);
  if (cpLength(text) + keyLength <= LENGTH_ALLOWANCE) return value;

  const budget = Math.max(0, BUDGET_BASE - keyLength - BUDGET_PER_LEVEL * keys.length);
  const cut = cpSlice(text, budget);
  // A shortened number stays a number as long as what is left still reads as
  // one (a bare "-" does not, and comes out quoted).
  if (typeof value !== 'string' && JSON_INTEGER.test(cut)) return new RawJson(cut);
  return cut;
}

function shorten(value, keys) {
  if (!(value instanceof Map)) return shortenLeaf(value, keys);
  const result = new Map();
  for (const [key, item] of value) {
    result.set(key, shorten(item, [...keys, key]));
  }
  return result;
}

export class Delta {
  constructor(diff) {
    this.diff = diff.deltaDict;
  }

  repr() {
    return `<Delta: ${jsonDumps(shorten(this.diff, []))}>`;
  }
}

