import random, subprocess, sys, os

EXE = "/workspace/dataset/test15_executable"
JS = ["node", "/output/test15.mjs"]

ALPHABET = list("ab\n\r\tX \\'\"0") + ["\n", "\n", "\r\n", "\x0b", "\x85", " ", "中", "😀", "\x00"]

def rand_a(rng):
    kind = rng.randrange(6)
    if kind == 0:
        n = rng.randrange(0, 40)
        return "".join(rng.choice(ALPHABET) for _ in range(n))
    if kind == 1:  # many lines
        n = rng.randrange(1, 20)
        return "\n".join(rng.choice(["l1", "l2", "l3", "x", "y", ""]) for _ in range(n))
    if kind == 2:  # long, near the shortening boundary
        n = rng.randrange(30, 40)
        return "".join(rng.choice("abcXY") for _ in range(n))
    if kind == 3:  # boundary lengths exactly
        n = rng.choice([32, 33, 34, 35, 36, 50])
        return rng.choice("qZ-") * n
    if kind == 4:
        n = rng.randrange(0, 6)
        return "".join(rng.choice(ALPHABET) for _ in range(n))
    n = rng.randrange(1, 250)
    return "".join(rng.choice("ab\n") for _ in range(n))

def rand_int(rng):
    kind = rng.randrange(5)
    if kind == 0:
        return str(rng.randrange(-10, 10))
    if kind == 1:
        return str(rng.randrange(-10**6, 10**6))
    if kind == 2:
        n = rng.choice([60, 66, 67, 68, 69, 70, 71, 72, 100])
        return rng.choice(["", "-"]) + "".join(rng.choice("123456789") for _ in range(n))
    if kind == 3:
        return rng.choice([" 5 ", "+7", "1_000", "0", "-0", "١٢٣", "１２３"])
    return str(rng.randrange(-10**20, 10**20))

def run(cmd, args):
    p = subprocess.run(cmd + args, capture_output=True)
    return p.returncode, p.stdout, p.stderr

def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    fails = 0
    for i in range(n):
        args = ["--a", rand_a(rng), "--b", rand_int(rng), "--c", rand_int(rng)]
        try:
            rc1, out1, err1 = run([EXE], args)
            rc2, out2, err2 = run(JS, args)
        except Exception as exc:
            print("runner error", exc, args)
            fails += 1
            continue
        err1 = err1.replace(b"test15_executable", b"PROG")
        err2 = err2.replace(b"test15.mjs", b"PROG")
        if (rc1, out1, err1) != (rc2, out2, err2):
            fails += 1
            print("FAIL", repr(args))
            print("  rc", rc1, rc2)
            if out1 != out2:
                a = out1.split(b"\n")
                b = out2.split(b"\n")
                for j in range(max(len(a), len(b))):
                    x = a[j] if j < len(a) else b"<missing>"
                    y = b[j] if j < len(b) else b"<missing>"
                    if x != y:
                        print("  line", j)
                        print("   py:", x[:400])
                        print("   js:", y[:400])
            if err1 != err2:
                print("  err py:", err1[:300])
                print("  err js:", err2[:300])
            if fails > 6:
                break
    print(f"{fails} failures out of {n}")

main()

